function nowIso(){return new Date().toISOString();}
function cloneLite(v){try{return JSON.parse(JSON.stringify(v));}catch(_){return String(v);}}
function log(type,data){debugLog.push({ts:nowIso(),type:type,data:cloneLite(data||{})});if(debugLog.length>20000)debugLog.splice(0,debugLog.length-20000);}
