 minX=Math.max(0,Math.floor(minX)-3);minY=Math.max(0,Math.floor(minY)-3);maxX=Math.min(CW,Math.ceil(maxX)+3);maxY=Math.min(CH,Math.ceil(maxY)+3);var bw=Math.max(1,maxX-minX),bh=Math.max(1,maxY-minY),ss=3,off=document.createElement('canvas');off.width=Math.ceil(bw*ss);off.height=Math.ceil(bh*ss);var ox=off.getContext('2d');ox.scale(ss,ss);ox.fillStyle='#2684ff';
 polys.forEach(function(poly){ox.beginPath();ox.moveTo(poly[0].x-minX,poly[0].y-minY);for(var i=1;i<poly.length;i++)ox.lineTo(poly[i].x-minX,poly[i].y-minY);ox.closePath();ox.fill();});
