function directionModelLabel(spec){if(isPlayerSpec(spec))return '正四向';if(isTerrain4Spec(spec))return '地形斜四向';if(isDiagonal4Spec(spec))return '斜四向';if(isOct8Spec(spec))return '真八向';if(isSingle4Spec(spec))return isGroundAssetSpec(spec)?'贴地单图斜四向复用':'单图斜四向复用';return specDirectionModel(spec);}
function eightSlotInfo(index){var list=[{key:'n',full:'上 / N'},{key:'ne',full:'右上 / NE'},{key:'e',full:'右 / E'},{key:'se',full:'右下 / SE'},{key:'s',full:'下 / S'},{key:'sw',full:'左下 / SW'},{key:'w',full:'左 / W'},{key:'nw',full:'左上 / NW'}];return list[((index%8)+8)%8];}
