  var outer=footprintOuterSize(spec),local=localRectPoly(outer.w,outer.d,1),out=[];
  for(var i=0;i<local.length;i++){var uv=groundLocalToAssetPixel(asset,state.viewRotation,local[i],outer,spec);if(uv)out.push(uv);}
  if(out.length>=3){poly=out;source='placement footprint projection';}
