 for(var i=0;i<prof.length;i++){
  if(prof[i].y>=maxY-tol){
   if(i<=bi)leftCand.push(prof[i]);
   if(i>=bi)rightCand.push(prof[i]);
  }
 }
 var L=leftCand.length?leftCand[0]:prof[0];
