 var R=rightCand.length?rightCand[rightCand.length-1]:prof[prof.length-1];
 if(B.x<=L.x+1)B={x:Math.round((L.x+R.x)*0.5),y:maxY};
 if(R.x<=B.x+1)R={x:prof[prof.length-1].x,y:prof[prof.length-1].y};
 var pad=Math.max(1,Math.round(b.w*0.02));
