 for(var vi=0;vi<views.length;vi++){maxW=Math.max(maxW,views[vi].asset.bbox.w);maxHpx=Math.max(maxHpx,views[vi].asset.bbox.h);}
 var res=clamp(Math.round(maxW*.72),44,72),levels=clamp(Math.round(maxHpx*.72),44,88),maxH=Math.max(.03,state.caster.proxyH||1),dx=outer.w/res,dy=outer.d/res;
 var key=['cz2',spec.id,state.caster.facing,state.playerAnimFrame,res,levels,outer.w.toFixed(3),outer.d.toFixed(3),maxH.toFixed(3),views.map(function(v){return v.url;}).join('|')].join('|');
