function clampCalibrationPanelToViewport(){
 var panel=document.getElementById('calibrationPanel');if(!panel)return;
 var topGap=Math.max(54,Math.min(64,Math.round(window.innerHeight*.08))),bottomGap=window.innerHeight<520?34:42,sideGap=window.innerWidth<520?6:10;
 panel.style.position='fixed';panel.style.left='auto';panel.style.right=sideGap+'px';panel.style.top=topGap+'px';panel.style.bottom=bottomGap+'px';
 panel.style.width=Math.max(220,Math.min(320,window.innerWidth-sideGap*2))+'px';panel.style.maxHeight=Math.max(120,window.innerHeight-topGap-bottomGap)+'px';panel.style.overflowY='auto';panel.style.overflowX='hidden';
 var r=panel.getBoundingClientRect();
 if(r.right>window.innerWidth-sideGap)panel.style.right=sideGap+'px';
 if(r.left<sideGap){panel.style.right=sideGap+'px';panel.style.width=Math.max(180,window.innerWidth-sideGap*2)+'px';}
 if(r.top<topGap)panel.style.top=topGap+'px';
 if(r.bottom>window.innerHeight-bottomGap)panel.style.bottom=bottomGap+'px';
}
