 var reset=document.getElementById('mappingReset');if(reset)reset.onclick=function(){state.toiletShadowMap=[0,3,2,1];state.toiletShadowFlip=[true,false,true,false];state.terrainShadowMap=[0,1,2,3];state.terrainShadowFlip=[true,false,true,false];state.playerShadowMap=[0,1,2,3];state.playerShadowFlip=[false,false,false,false];log('shadow-map-reset',{object:state.toiletShadowMap.slice(),objectFlip:state.toiletShadowFlip.slice(),player:state.playerShadowMap.slice(),playerFlip:state.playerShadowFlip.slice(),rule:'diagonal4 parity fixed: NE/SW flip, SE/NW no-flip'});queueRender();};
 updateCalibrationPanel();
